mapper.select:
select
banners.*
from banners banners

    and banners.id = #{id}
    and banners.banner_url = #{bannerUrl}
    and banners.create_time = #{createTime}
    and banners.banner_name like concat('%',#{bannerName},'%')
    and banners.content = #{content}


    limit #{current},#{pageSize}

select count(*) from banners banners

    and banners.id = #{id}
    and banners.banner_url = #{bannerUrl}
    and banners.create_time = #{createTime}
    and banners.banner_name like concat('%',#{bannerName},'%')
    and banners.content = #{content}
